pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Deposit{value: 2 ether}();
        // alice's balance is 2 ether
        uint preBal = c.balances(alice);
        vm.prank(alice);
        (bool success,) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", 1.5 ether));
        assertTrue(success ? c.balances(alice) == 0.5 ether : c.balances(alice) == 2 ether);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 3 ether);
        vm.deal(bob, 2 ether);

        // Alice deposits 2 ether (above MinDeposit 1 ether)
        vm.prank(alice);
        c.Deposit{value: 2 ether}();

        // Bob deposits 1 ether (above MinDeposit)
        vm.prank(bob);
        c.Deposit{value: 1 ether}();

        // Alice attempts to withdraw exactly her balance (2 ether)
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("CashOut(uint256)", 2 ether));

        // In reference (<=), alice's balance becomes 0; in bug (<), it stays 2
        uint256 aliceBalance = c.balances(alice);
        assertTrue(aliceBalance == 0, "Alice balance should be 0 after withdrawing full balance");
    }
}
